"""Independently verify selection, cached causal readout, metrics and contrasts."""
from pathlib import Path
import json,hashlib,datetime
import numpy as np
OUT=Path('results/thrml_spw/boolean_classifier_cached_reuse');PARENT=Path('results/thrml_spw/boolean_classifier')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    e=json.loads((OUT/'execution_protocol.json').read_text());p=json.loads((OUT/'protocol.json').read_text());r=json.loads((OUT/'evaluation.json').read_text())
    for f,h in e['source_sha256'].items():assert sha(f)==h
    for key,file in [('selection_protocol_sha256',OUT/'protocol.json'),('execution_protocol_sha256',OUT/'execution_protocol.json'),('parent_completion_sha256',PARENT/'completion.json'),('parent_statistical_arrays_sha256',PARENT/'statistical_arrays.npz'),('selected_counts_sha256',OUT/'selected_counts.npz'),('predictions_losses_sha256',OUT/'derived_predictions_losses.npz'),('statistics_sha256',OUT/'statistics.npz')]:assert sha(file)==r[key]
    prep=json.loads(Path('results/thrml_spw/boolean_classifier_preparation_v2/preparation.json').read_text());data=np.load(prep['data_path']);x=data['test_inputs'].astype(float).reshape(1250,8,64);y=data['test_labels'];c=np.load(OUT/'selected_counts.npz');saved=np.load(OUT/'derived_predictions_losses.npz');s=np.load(OUT/'statistics.npz');parent=np.load(PARENT/'statistical_arrays.npz');value=np.empty((3,5,10,2));rows={(a['model'],a['budget_index'],a['seed']):a for a in r['rows']};subset=0
    for item in p['selected']:
        mi,bi,si,t=item['model'],item['budget_index'],item['seed'],item['T'];assert sha(item['parent_path'])==item['parent_sha256'];raw=np.load(item['parent_path']);np.testing.assert_array_equal(c['weight_0'][mi,bi,si],raw['weight_0'][0]);np.testing.assert_array_equal(c['weight_1'][mi,bi,si],raw['weight_1'][0]);model=np.load(prep['models'][mi]['controls_path']);w0=c['weight_0'][mi,bi,si].astype(float)/t;w1=c['weight_1'][mi,bi,si].astype(float)/t;h=np.maximum(np.matmul(x,w0)+model['bias_0'],0);z=(np.matmul(h,w1)+model['bias_1']).reshape(10000,10);alt_h=np.maximum(np.einsum('bmi,io->bmo',x,w0,optimize=False)+model['bias_0'],0);alt_z=(np.einsum('bmi,io->bmo',alt_h,w1,optimize=False)+model['bias_1']).reshape(10000,10);np.testing.assert_allclose(z,alt_z,rtol=2e-12,atol=2e-11);assert hashlib.sha256(np.ascontiguousarray(z).tobytes()).hexdigest()==rows[mi,bi,si]['all_logits_byte_sha256'];np.testing.assert_array_equal(z[:8],raw['logits'][:8]);pred=z.argmax(1).astype(np.uint8);top=z.max(1);loss=top+np.log(np.exp(z-top[:,None]).sum(1))-z[np.arange(10000),y];np.testing.assert_array_equal(pred,saved['predictions'][mi,bi,si]);np.testing.assert_allclose(loss,saved['losses'][mi,bi,si],rtol=2e-12,atol=2e-13);value[bi,mi,si]=[np.count_nonzero(pred==y)/10000,loss.mean()];subset+=2368*t
    np.testing.assert_allclose(value,s['values'],rtol=2e-12,atol=2e-13);assert subset==243667200==p['native_updates_in_selected_existing_subset'];assert p['additional_F64_reconstructed_weight_cache_bits']==(64*32+32*10)*64
    for bi,row in enumerate(r['summaries']):
        delta=value[bi]-parent['values'][0,bi];models,seeds=parent['bootstrap_models'],parent['bootstrap_seeds'];dist=sum(delta[models[:,i,None],seeds[:,i,:]].sum(1) for i in range(5))/50;np.testing.assert_allclose(dist,s[f'budget{bi}'],rtol=2e-10,atol=2e-12);np.testing.assert_allclose(delta.mean((0,1)),row['cached_minus_per_bank'],rtol=2e-10,atol=2e-12);np.testing.assert_allclose(value[bi].mean((0,1)),row['cached_mean'],rtol=2e-12,atol=2e-13);np.testing.assert_allclose(parent['values'][0,bi].mean((0,1)),row['per_bank_mean'],rtol=2e-12,atol=2e-13);np.testing.assert_allclose(np.quantile(dist,[.025,.975],axis=0).T,row['descriptive_95_interval'],rtol=2e-10,atol=2e-12)
    result={'passed':True,'cached_cases_checked':150,'cached_logits_exact_sha_checked':15000000,'predictions_and_losses_checked':1500000,'bootstrap_values_checked':30000,'evaluation_sha256':sha(OUT/'evaluation.json'),'source_sha256':sha(__file__),'new_native_updates':0,'scope':'All selected first-bank counts, full causal outputs via exact byte hashes plus separate contraction reference, predictions/losses, reused parent bootstrap contrasts and cache/conditional update ledger checked.'};(OUT/'evidence_audit.json').write_text(json.dumps(result,indent=2)+'\n')
    lines=['# Static reconstructed-weight reuse control','','This derived control was selected before its quality scoring and reuses bank0 of all150 original R1 cases. The parent full cohort passed native/statistical audits before this evaluation ran. There are no new sampler draws, independent MC replications or fresh test images. All original R1/R3 results/resource receipts remain unchanged.','','| Samples/layer | Cached accuracy (%) | Per-bank accuracy (%) | Cached CE | Per-bank CE |','|---:|---:|---:|---:|---:|']
    for row in r['summaries']:lines.append(f"| {row['T']} | {100*row['cached_mean'][0]:.4f} | {100*row['per_bank_mean'][0]:.4f} | {row['cached_mean'][1]:.8f} | {row['per_bank_mean'][1]:.8f} |")
    lines+=['','Every first-bank reconstruction is reused for all10000 examples; dense arithmetic and F64 weight caching remain conventional. A hypothetical deployment therefore samples one bank rather than1250 banks but retains18944bytes of reconstructed matrix weights per model, beyond bias commands and external activations/readouts. Merely retaining probability/bias settings does not provide this reconstructed cache. No physical memory/energy/latency advantage follows.','','The selected existing trajectories contain243,667,200 scheduled updates, already included in the original304,584,000,000 executed R1 updates. The original executed work is not reduced retroactively. The1250fold sampling reduction is counterfactual deployment accounting conditional on weight caching, not a measured end-to-end speedup.','','Expected dataset-average quality agrees for cached versus resampled policies when each input has the same sampled-weight law, by linearity of expectation. Finite-run variance differs because a cached perturbation is shared across all examples. All paired descriptive intervals, three budgets and five-model/ten-seed outcomes are retained in evaluation.json; the bootstrap reuses parent model/seed index draws and fixes consumed test images. No favorable bank was selected.','','[Evaluation](boolean_classifier_cached_reuse/evaluation.json) · [Independent audit](boolean_classifier_cached_reuse/evidence_audit.json) · [Selection protocol](boolean_classifier_cached_reuse/protocol.json).','','The broader research goal remains active.']
    report=Path('results/thrml_spw/BOOLEAN_CLASSIFIER_CACHED_REUSE_REPORT.md');report.write_text('\n'.join(lines)+'\n');paths=[OUT/'protocol.json',OUT/'execution_protocol.json',OUT/'selected_counts.npz',OUT/'evaluation.json',OUT/'derived_predictions_losses.npz',OUT/'statistics.npz',OUT/'evidence_audit.json',report];(OUT/'completion.json').write_text(json.dumps({'status':'derived_static_cache_control_audited_goal_active','recorded_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'new_native_updates':0,'artifact_sha256':{str(v):sha(v) for v in paths}},indent=2)+'\n');print('Independent static-cache control audit/report complete',flush=True)
if __name__=='__main__':main()
